def execute(node_id, node_data, context):
    import hashlib
    import time
    from urllib.parse import quote, urlencode

    mixin_key_enc_tab = [
        46, 47, 18, 2, 53, 8, 23, 32, 15, 50, 10, 31, 58, 3, 45, 35,
        27, 43, 5, 49, 33, 9, 42, 19, 29, 28, 14, 39, 12, 38, 41, 13,
        37, 48, 7, 16, 24, 55, 40, 61, 26, 17, 0, 1, 60, 51, 30, 4,
        22, 25, 54, 21, 56, 59, 6, 63, 57, 62, 11, 36, 20, 34, 44, 52,
    ]
    rank_slugs = {
        1005: 'douga',
        1008: 'game',
        1007: 'kichiku',
        1003: 'music',
        1004: 'dance',
        1001: 'cinephile',
        1002: 'ent',
        1010: 'knowledge',
        1012: 'tech',
        1020: 'food',
        1013: 'car',
        1014: 'fashion',
        1018: 'sports',
        1024: 'animal',
    }

    def key_from_url(value):
        if not value:
            return ''
        return value.rsplit('/', 1)[-1].split('.', 1)[0]

    def sign(params, img_key, sub_key):
        raw_key = img_key + sub_key
        mixin_key = ''.join(raw_key[index] for index in mixin_key_enc_tab)[:32]
        wts = int(time.time())
        signed_params = {**params, 'wts': wts}

        def clean(value):
            return ''.join(char for char in str(value) if char not in "!'()*")

        query = '&'.join(
            f'{quote(str(key), safe="")}={quote(clean(value), safe="")}'
            for key, value in sorted(signed_params.items())
            if value is not None
        )
        signed_params['w_rid'] = hashlib.md5((query + mixin_key).encode()).hexdigest()
        return signed_params

    def add_cookie(cookies, key, value):
        if value:
            cookies.append(f'{key}={value}')

    try:
        rid = int(context.get('rid') or 0)
    except (TypeError, ValueError):
        rid = 0

    ticket = context.get('biliTicket') or {}
    nav = ticket.get('nav') or {}
    wbi_img = context.get('biliWbiImg') or {}
    img_key = key_from_url(nav.get('img') or wbi_img.get('img_url')) or 'c458435a75b1419ca98ab6d88b4c60d4'
    sub_key = key_from_url(nav.get('sub') or wbi_img.get('sub_url')) or '446140f6859f439e9dd83f7ef858d1cd'
    params = sign({'rid': rid, 'type': 'all'}, img_key, sub_key)
    slug = rank_slugs.get(rid)

    finger = context.get('biliFinger') or {}
    cookies = []
    add_cookie(cookies, 'buvid3', finger.get('b_3'))
    add_cookie(cookies, 'buvid4', finger.get('b_4'))
    if finger.get('b_3'):
        add_cookie(cookies, 'b_nut', int(time.time()))
    add_cookie(cookies, 'bili_ticket', ticket.get('ticket'))
    if ticket.get('created_at') and ticket.get('ttl'):
        add_cookie(cookies, 'bili_ticket_expires', int(ticket.get('created_at')) + int(ticket.get('ttl')))

    context['rank_query'] = urlencode(params)
    context['rank_referer'] = (
        f'https://www.bilibili.com/v/popular/rank/{slug}'
        if slug else 'https://www.bilibili.com/v/popular/rank'
    )
    context['bili_cookie'] = '; '.join(cookies)

